    if choice == 0:
        # all equal elements
        v = draw(st.integers(1, 16))
        a = [v] * n
    elif choice == 1:
        # sorted ascending
        a = sorted(draw(st.lists(st.integers(1, 40), min_size=n, max_size=n)))
    elif choice == 2:
        # sorted descending
        a = sorted(draw(st.lists(st.integers(1, 40), min_size=n, max_size=n)), reverse=True)
    else:
        # general small values, including extremes of a scaled-down range
        a = draw(st.lists(st.one_of(st.integers(1, 3), st.integers(1, 100)),
                          min_size=n, max_size=n))
    return f"{n}\n{' '.join(map(str, a))}\n"

